// ====== EDIT THESE TWO VALUES (or replace this node with a Form/Webhook trigger) ======
const sourceContent = `PASTE YOUR LONG-FORM CONTENT HERE — a blog post, article, or YouTube transcript.`;
const brandVoice = `Professional but warm. Plain English, no jargon, no emojis, no hype words like "revolutionary".`;
// =====================================================================================

const system = `You are a senior content strategist and copywriter. You repurpose long-form content into platform-native social content. Respond with VALID JSON ONLY (no markdown, no backticks) matching exactly this schema: {"linkedin_post": string, "x_thread": string[], "newsletter": {"subject": string, "body": string}, "instagram_caption": string}`;

const user = `BRAND VOICE:\n${brandVoice}\n\nSOURCE CONTENT:\n${sourceContent}\n\nProduce:\n1) linkedin_post: one post (strong first-line hook, then value, then a soft CTA), ~1300 characters.\n2) x_thread: an array of tweets. The first tweet must be a scroll-stopping hook. Each tweet <= 280 characters. 5-8 tweets.\n3) newsletter: a subject line under 60 chars and a short body (~150 words).\n4) instagram_caption: one caption ending with 3-5 relevant hashtags.`;

return [{
  json: {
    openaiBody: {
      model: "gpt-4o-mini",
      temperature: 0.7,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: system },
        { role: "user", content: user }
      ]
    }
  }
}];

const raw = $input.first().json.choices?.[0]?.message?.content;

if (!raw) {
  return [{ json: { error: 'No content returned from the model', full_response: $input.first().json } }];
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { error: 'Model did not return valid JSON', raw } }];
}

return [{ json: parsed }];
